-- ML Price Intelligence Phase L: district (kecamatan) Kota Padang
-- Feature contract V1 (ML_PRICE_INTELLIGENCE §7) mewajibkan `district`;
-- skema KOSTARA sebelumnya tidak punya field district sama sekali.
--
-- PROVENANCE (wajib untuk evidence, jangan dihapus):
--   sumber   : https://raw.githubusercontent.com/cahyadsn/wilayah_boundaries/main/db/kec/wilayah_boundaries_kec_13.sql
--   repo     : cahyadsn/wilayah_boundaries (MIT License)
--   basis    : data batas administrasi Kepmendagri No 300.2.2-2430 Tahun 2025
--   file     : wilayah_boundaries_kec_13.sql (Sumatera Barat, 179 kecamatan)
--   sha256   : 94ef0987604387c654eac37dea53c92c90d7c08db65cf5713346a950775454bf
--   ekstrak  : 2026-09-26, filter kode 13.71.* (Kota Padang = 11 kecamatan)
--   koordinat sumber [lat,lng] → dikonversi ke GeoJSON [lng,lat]
--
-- CATATAN JUJUR (limitasi, bukan disembunyikan):
--   - geometri berasal dari data simplified (multipolygon ringkas);
--     terdeteksi overlap antar-kecamatan hingga ~1,1 km² (cek ST_Overlaps).
--   - titik di pita overlap bisa match >1 kecamatan → tie-break deterministik
--     `order by kode limit 1` (kode terkecil menang); dicatat di DQ export.
--   - subdistrict/kelurahan TIDAK dimuat di V1 (ukuran & cakupan) →
--     `subdistrict` = null, dicatat sebagai data gap.

create table public.districts (
  kode text primary key,
  nama text not null unique,
  geom geometry(MultiPolygon, 4326) not null,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

