create index districts_geom_gist on public.districts using gist (geom);

-- titik → nama kecamatan (point-in-polygon; tie-break kode terkecil saat overlap)
create or replace function public.district_for_point(pt geometry)
returns text
language sql stable security definer set search_path = public, pg_temp as $$
  select d.nama
  from public.districts d
  where d.is_active
    and d.geom && pt
    and ST_Covers(d.geom, pt)
  order by d.kode
  limit 1;
$$;
revoke all on function public.district_for_point(geometry) from public;
grant execute on function public.district_for_point(geometry) to service_role;

-- kolom turunan properties: selalu dihitung dari lokasi, client tidak bisa set manual
alter table public.properties add column district text references public.districts(nama);

create or replace function public.properties_district_fn()
returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  new.district := public.district_for_point(new.location::geometry);
  return new;
end;
$$;
create trigger properties_district
  before insert or update of location, district on public.properties
  for each row execute function public.properties_district_fn();

-- backfill baris lama (trigger ikut menghitung ulang, hasil identik)
update public.properties p
set district = public.district_for_point(p.location::geometry)
where p.district is null;

-- RLS: referensi baca-saja (pola master data: publik hanya is_active;
-- tanpa policy insert/update/delete → tulis hanya via migration/service role)
alter table public.districts enable row level security;
create policy districts_select_active on public.districts
  for select
  using (is_active = true or public.app_is_admin());
